/**
 * Collect every icon the source actually names into one offline bundle.
 *
 * `@iconify/react` fetches icon data from api.iconify.design at runtime.
 * On a cold load that was three extra cross-origin requests, and it makes
 * the icons in the interface depend on a third-party CDN being reachable —
 * for a product people pay for, that is a dependency we do not want.
 *
 * This reads the `@iconify-json/*` packages (devDependencies, so none of
 * this ships) and writes only the icons the code mentions. Anything it
 * cannot find is reported and simply left to the network, which is the
 * library's normal behaviour, so a missed icon degrades instead of
 * vanishing.
 *
 * Re-run after adding icons:  npm run icons
 */
import { readFileSync, writeFileSync, readdirSync, statSync } from 'node:fs';
import { join, extname } from 'node:path';
import { createRequire } from 'node:module';

const require = createRequire(import.meta.url);
const PREFIXES = ['heroicons-outline', 'heroicons', 'simple-icons', 'clarity', 'mdi', 'bi', 'ph'];
const NAME = new RegExp(`["']((?:${PREFIXES.join('|')}):[a-z0-9][a-z0-9-]*)["']`, 'g');

const walk = (dir, out = []) => {
  for (const entry of readdirSync(dir)) {
    const p = join(dir, entry);
    if (statSync(p).isDirectory()) walk(p, out);
    else if (['.js', '.jsx'].includes(extname(p))) out.push(p);
  }
  return out;
};

const wanted = new Map();
for (const file of walk('src')) {
  const text = readFileSync(file, 'utf8');
  for (const [, full] of text.matchAll(NAME)) {
    const [prefix, name] = full.split(/:(.*)/);
    if (!wanted.has(prefix)) wanted.set(prefix, new Set());
    wanted.get(prefix).add(name);
  }
}

const collections = [];
const missing = [];
for (const [prefix, names] of [...wanted].sort()) {
  let source;
  try {
    source = JSON.parse(readFileSync(require.resolve(`@iconify-json/${prefix}/icons.json`), 'utf8'));
  } catch {
    missing.push(`${prefix}: package @iconify-json/${prefix} not installed`);
    continue;
  }
  const icons = {};
  const aliases = {};
  for (const name of [...names].sort()) {
    if (source.icons?.[name]) {
      icons[name] = source.icons[name];
      continue;
    }
    // An alias points at another icon, possibly through several hops.
    // Both the alias and whatever it finally resolves to have to travel.
    let cursor = name;
    const chain = [];
    while (source.aliases?.[cursor] && chain.length < 8) {
      chain.push(cursor);
      cursor = source.aliases[cursor].parent;
    }
    if (chain.length && source.icons?.[cursor]) {
      chain.forEach((a) => { aliases[a] = source.aliases[a]; });
      icons[cursor] = source.icons[cursor];
    } else {
      missing.push(`${prefix}:${name}`);
    }
  }
  const collection = { prefix, icons, aliases };
  for (const key of ['width', 'height', 'left', 'top', 'rotate', 'hFlip', 'vFlip']) {
    if (source[key] !== undefined) collection[key] = source[key];
  }
  collections.push(collection);
  console.log(`${prefix.padEnd(18)} ${Object.keys(icons).length} icons, ${Object.keys(aliases).length} aliases`);
}

const out = `// GENERATED by scripts/build-icon-bundle.mjs — do not edit by hand.
// Re-run \`npm run icons\` after adding or renaming an icon.
export default ${JSON.stringify(collections)};
`;
writeFileSync('src/icons/offline.js', out);

const bytes = Buffer.byteLength(out);
console.log(`\nsrc/icons/offline.js  ${(bytes / 1024).toFixed(1)} kB`);
if (missing.length) {
  console.log(`\n${missing.length} icon(s) not bundled (they will still load from the network):`);
  missing.forEach((m) => console.log('  ' + m));
}
